let transferView={kind:'all',level:'all',preview:null,input:null,name:'',filter:'all',limit:20,error:'',result:null,reading:false},transferReadToken=0;
function transferRecords(){const kotoba=customRead('kotoba'),kanji=customRead('kanji');if(kotoba===null||kanji===null)throw Error('Data buatanmu belum dapat dibaca. Penyimpanan tidak diubah; coba muat ulang halaman.');return {kotoba:customRecords('kotoba'),kanji:customRecords('kanji')}}
function transferBases(){return {kotoba:['N5','N4'].flatMap(level=>kotobaBaseEntries(level).flatMap(r=>[r.jp,...r.aliases].map(jp=>({jp,level})))),kanji:[...KANJI_DATA,...KANJI_N4_DATA].map(r=>({jp:r.char}))}}
function transferSet(key,value){if(key==='kind'&&!['all','kotoba','kanji'].includes(value)||key==='level'&&!['all','N5','N4'].includes(value)||!['kind','level'].includes(key))return;transferView[key]=value;render()}
function transferGroup(label,key,choices){return `<div class="transfer-choice" role="group" aria-label="${label}">${choices.map(([value,name])=>`<button type="button" aria-pressed="${transferView[key]===value}" onclick="transferSet('${key}','${value}')">${name}</button>`).join('')}</div>`}
function transferPreview(){const p=transferView.preview;if(!p)return '';const labels={new:'Data baru',duplicate:'Duplikat',invalid:'Perlu diperbaiki'},list=p.rows.filter(r=>transferView.filter==='all'||r.status===transferView.filter),shown=list.slice(0,transferView.limit);return `<section class="transfer-card transfer-preview" aria-label="Pratinjau impor"><span class="transfer-step">2 · PERIKSA ISINYA</span><h2>Pratinjau sebelum disimpan</h2><p>${esc(transferView.name)} · ${p.rows.length} baris</p><div class="transfer-counts">${Object.entries(p.counts).map(([k,v])=>`<div><b>${v}</b><span>${labels[k]}</span></div>`).join('')}</div><p class="transfer-note">Impor menambahkan data baru. Duplikat dan baris bermasalah dilewati; data yang sudah tersimpan tetap dipertahankan.</p><div class="transfer-preview-filters" role="group" aria-label="Status baris impor">${[['all','Semua'],...Object.entries(labels)].map(([k,v])=>`<button aria-pressed="${transferView.filter===k}" onclick="transferView.filter='${k}';transferView.limit=20;render()">${v}</button>`).join('')}</div><div class="transfer-rows">${shown.length?shown.map(r=>`<article><div><small>${r.kind==='kotoba'?'Kotoba':'Kanji'} · baris ${r.index}${r.level?' · '+r.level:''}</small><h3 lang="ja">${esc(r.jp)}</h3>${r.reading?`<p class="transfer-row-reading">${esc(r.reading)}</p>`:''}${r.meaning?`<p>Arti di file: ${esc(r.meaning)}</p>`:''}<p>${esc(r.message)}</p></div><span class="transfer-tag ${r.status}">${labels[r.status]}</span></article>`).join(''):'<p>Tidak ada baris dalam pilihan ini.</p>'}</div>${list.length>shown.length?'<button class="transfer-secondary" onclick="transferView.limit+=20;render()">Tampilkan 20 lagi</button>':''}<div class="transfer-actions"><button class="primary" onclick="transferApply()" ${p.counts.new?'':'disabled'}>Impor ${p.counts.new} data baru</button><button class="transfer-secondary" onclick="transferCancel()">Batal</button></div><p class="transfer-note">${p.add.kotoba.length} Kotoba dan ${p.add.kanji.length} Kanji siap ditambahkan. Perbaiki baris bermasalah di file JSON, lalu pilih ulang bila diperlukan.</p></section>`}
function transferScreen(){if(!GakuPremium.has('import_export'))return GakuPremium.wall('import_export');let records={kotoba:[],kanji:[]},readError='';try{records=transferRecords()}catch(e){readError=e.message}const pending=GakuTransfer.pending(),selected=GakuTransfer.exportObject(records,transferView.kind,transferView.level),count=selected.data.kotoba.length+selected.data.kanji.length;return title('Import–Export','Cadangkan dan pindahkan Kotoba serta Kanji buatanmu.')+`<div class="transfer-page">${pending?`<div class="transfer-warning" role="alert"><h2>Penyimpanan perlu diselesaikan</h2><p>${pending==='committed'?'Impor sudah tersimpan. Salinan penyimpanannya masih perlu diselesaikan.':pending==='prepared'?'Impor sebelumnya belum selesai. Data sebelum impor tetap dipertahankan.':'Catatan pemulihan belum dapat dibaca. Data tidak ditimpa.'}</p><button class="transfer-secondary" onclick="transferRecover()">Coba pulihkan penyimpanan</button></div>`:''}${readError?`<p class="transfer-warning" role="alert">${esc(readError)}</p>`:''}<section class="transfer-card"><span class="transfer-step">EKSPOR · SIMPAN CADANGAN</span><h2>Bawa data belajarmu</h2><p>Unduh file JSON untuk dipakai kembali di perangkat lain. Isinya data buatanmu; materi bawaan, riwayat, favorit, dan pengaturan tidak ikut diekspor.</p><div class="transfer-counts"><div><b>${records.kotoba.length}</b><span>Kotoba buatanmu</span></div><div><b>${records.kanji.length}</b><span>Kanji buatanmu</span></div></div><h3>Pilih isi cadangan</h3>${transferGroup('Jenis data ekspor','kind',[['all','Keduanya'],['kotoba','Kotoba'],['kanji','Kanji']])}${transferGroup('Level data ekspor','level',[['all','Semua level'],['N5','N5'],['N4','N4']])}<button class="primary" onclick="transferExport()" ${readError||!count?'disabled':''}>Unduh JSON · ${count} data</button>${!count?'<p class="transfer-note">Belum ada data dalam pilihan ini. Tambahkan data atau pilih level lainnya.</p>':''}</section><section class="transfer-card"><span class="transfer-step">1 · PILIH FILE IMPOR</span><h2>Masukkan cadanganmu</h2><p>Pilih JSON hasil Ekspor DeX Gaku. Bacaan, arti, contoh, dan level mengikuti file yang kamu pilih.</p><label class="transfer-file" for="transfer-file">Pilih file JSON<input id="transfer-file" type="file" accept=".json,application/json" onchange="transferReadFile(this.files[0])"></label><p class="transfer-note">Maksimal 5 MB dan 5.000 baris per file. Memilih file hanya membuka pratinjau.</p><button class="transfer-link" onclick="transferTemplate()">Unduh contoh format JSON</button>${transferView.reading?'<p role="status">Sedang membaca file…</p>':''}${transferView.error?`<p class="transfer-warning" role="alert">${esc(transferView.error)}</p>`:''}</section>${transferView.result?`<section class="transfer-success" role="status"><h2>Impor selesai</h2><p>${transferView.result.kotoba} Kotoba dan ${transferView.result.kanji} Kanji ditambahkan. ${transferView.result.duplicate} duplikat dan ${transferView.result.invalid} baris bermasalah dilewati.</p><div class="transfer-actions"><button class="transfer-secondary" onclick="showPage('Tambah data')">Lihat data buatanmu</button><button class="transfer-secondary" onclick="transferExport()">Unduh cadangan</button></div></section>`:''}${transferPreview()}<p class="transfer-local">Proses berlangsung di browser perangkat ini. Simpan file cadangan di tempat yang mudah kamu temukan.</p></div>`}
function transferDownload(object,name){const blob=new Blob([JSON.stringify(object,null,2)+'\n'],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function transferExport(){if(!GakuPremium.require('import_export'))return;try{const object=GakuTransfer.exportObject(transferRecords(),transferView.kind,transferView.level);if(!object.data.kotoba.length&&!object.data.kanji.length){toast('Belum ada data untuk diekspor dalam pilihan ini.');return}const d=new Date(),stamp=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');transferDownload(object,'DeX-Gaku-Data-'+stamp+'.json');toast('File cadangan siap diunduh.')}catch(e){toast(e.message||'Cadangan belum dapat diunduh.')}}
function transferTemplate(){if(!GakuPremium.require('import_export'))return;transferDownload({format:GakuTransfer.FORMAT,version:1,data:{kotoba:[{jp:'さくら',kana:'さくら',rom:'sakura',meaning:'bunga sakura',level:'N5'}],kanji:[{jp:'森',meaning:'hutan',level:'N4',on:['シン'],kun:['もり'],examples:[{word:'森林',kana:'しんりん',meaning:'hutan'}]}]}},'DeX-Gaku-Contoh-Format.json');toast('Contoh format perlu diubah sesuai datamu. Contoh yang sudah ada akan dilewati.')}
function transferCancel(){transferReadToken++;transferView.preview=null;transferView.input=null;transferView.error='';transferView.reading=false;render()}
function transferBuild(input,name){const records=transferRecords(),preview=GakuTransfer.plan(input,records,transferBases());preview.before=GakuTransfer.snapshot();transferView.preview=preview;transferView.input=input;transferView.name=name;transferView.filter='all';transferView.limit=20;return preview}
async function transferReadFile(file){if(!GakuPremium.require('import_export'))return;const accountEpoch=GakuPremium.epoch;const mine=++transferReadToken;transferView.preview=null;transferView.input=null;transferView.error='';transferView.result=null;if(!file){transferView.reading=false;render();return}if(!/\.json$/i.test(file.name)||file.size>GakuTransfer.MAX_BYTES){transferView.reading=false;transferView.error='Pilih file .json berukuran maksimal 5 MB.';render();return}transferView.reading=true;render();try{const content=await file.text();if(mine!==transferReadToken||accountEpoch!==GakuPremium.epoch||!GakuPremium.has('import_export'))return;transferBuild(GakuTransfer.parse(content),file.name)}catch(e){if(mine===transferReadToken)transferView.error=e.message||'File belum bisa dibaca.'}finally{if(mine===transferReadToken){transferView.reading=false;if(page==='Import–Export')render()}}}
function transferApply(){if(!GakuPremium.require('import_export'))return;const old=transferView.preview,input=transferView.input;if(!old||!input||!old.counts.new)return;try{const latest=GakuTransfer.snapshot();if(Object.keys(latest).some(k=>latest[k]!==old.before[k])){transferBuild(input,transferView.name);render();toast('Data perangkat berubah. Periksa pratinjau terbaru, lalu tekan Impor lagi.');return}const records=transferRecords(),plan=GakuTransfer.plan(input,records,transferBases()),after={};for(const k of ['kotoba','kanji']){const added=plan.add[k].map((r,i)=>({...r,customId:'user-import-'+Date.now().toString(36)+'-'+k+'-'+i+'-'+Math.random().toString(36).slice(2)}));after[k]=JSON.stringify([...records[k],...added])}const result=GakuTransfer.commit(after,latest);if(!result.ok){if(result.changed){transferBuild(input,transferView.name);toast('Data perangkat berubah. Periksa pratinjau terbaru.')}else toast(result.message);render();return}customData=customRead('kotoba')||[];transferView.result={kotoba:plan.add.kotoba.length,kanji:plan.add.kanji.length,duplicate:plan.counts.duplicate,invalid:plan.counts.invalid};transferView.preview=null;transferView.input=null;transferView.error='';const levels=[...new Set([...plan.add.kotoba,...plan.add.kanji].map(r=>r.level))];addHistory('Tambah data',`Impor ${plan.add.kotoba.length} Kotoba dan ${plan.add.kanji.length} Kanji`,{level:levels.join(' / ')});render();toast('Data baru berhasil diimpor.')}catch(e){toast(e.message||'Impor belum bisa diselesaikan. Data sebelumnya tetap dipertahankan.')}}
function transferRecover(){if(GakuTransfer.settle()){customData=customRead('kotoba')||[];render();toast('Penyimpanan sudah diselesaikan.')}else{render();toast('Penyimpanan belum dapat dipulihkan. Data tetap dipertahankan.')}}
